"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";
import { Star } from "./icons";

// Rating: generated by UIX from the design system. Same variants and sizes as the Figma component.

const ratingVariants = cva(
  "skin-quiet inline-flex items-center [&_svg]:shrink-0",
  {
    variants: {
      size: {
        sm: "gap-0.5 has-[button]:gap-0 [&>button]:p-1 [&_svg]:size-4",
        md: "gap-1 [&_svg]:size-6",
      },
    },
    defaultVariants: {
      size: "md",
    },
  },
);

export interface RatingProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange">,
    VariantProps<typeof ratingVariants> {
  /** Stars filled, 0 to max. */
  value?: number;
  /** Number of stars. */
  max?: number;
  /** Makes the stars buttons and calls this with the star that was pressed. */
  onValueChange?: (value: number) => void;
}

const Rating = React.forwardRef<HTMLDivElement, RatingProps>(
  ({ className, size, value = 0, max = 5, onValueChange, ...props }, ref) => {
    const stars = Array.from({ length: max }, (_, index) => index + 1);
    const starClass = (star: number) => (star <= value ? "fill-warning text-warning" : "fill-transparent text-line-strong");
    return (
      <div data-slot="rating" data-kind="chip" ref={ref} role={onValueChange ? "radiogroup" : "img"} aria-label={onValueChange ? "Rating" : value + " out of " + max} className={cn(ratingVariants({ size }), className)} {...props}>
        {stars.map((star) =>
          onValueChange ? (
            <button key={star} type="button" role="radio" aria-checked={star === value} aria-label={star + (star === 1 ? " star" : " stars")} onClick={() => onValueChange(star)} className="inline-flex cursor-pointer rounded-xs focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus">
              <Star aria-hidden className={starClass(star)} />
            </button>
          ) : (
            <Star key={star} aria-hidden className={starClass(star)} />
          ),
        )}
      </div>
    );
  },
);
Rating.displayName = "Rating";

export { Rating, ratingVariants };
